/** @param {{des: object}} api */
export default function bigrm_1({ des, selection, percent, math, luaList, luaLen }) {
    des.level_init({ style: 'solidfill', fg: ' ' });
    des.level_flags('mazelevel', 'noflip');

    des.map(`---------------------------------------------------------------------------
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
---------------------------------------------------------------------------
`);

    if (percent(80)) {
        // luaList keeps Lua's 1-based indices, so terrains[n] means the same here.
        const terrains = luaList('-', 'F', 'L', 'T', 'C');
        const tidx = math.random(1, luaLen(terrains));
        const choice = math.random(0, 5);
        if (choice === 0) {
            // one horizontal line
            des.terrain(selection.line(10, 8, 65, 8), terrains[tidx]);
        } else if (choice === 1) {
            // two vertical lines
            const sel = selection.bor(selection.line(15, 4, 15, 13), selection.line(59, 4, 59, 13));
            des.terrain(sel, terrains[tidx]);
        } else if (choice === 2) {
            // plus sign
            const sel = selection.bor(selection.line(10, 8, 64, 8), selection.line(37, 3, 37, 14));
            des.terrain(sel, terrains[tidx]);
        } else if (choice === 3) {
            // brackets:  [  ]
            des.terrain(selection.rect(4, 4, 70, 13), terrains[tidx]);
            const sel = selection.bor(selection.line(25, 4, 50, 4), selection.line(25, 13, 50, 13));
            des.terrain(sel, '.');
        } else if (choice === 4) {
            // snake
            des.terrain(selection.fillrect(5, 5, 69, 12), terrains[tidx]);
            for (let i = 0; i <= 7; i++) {
                const x = 6 + i * 8;
                const y = 5 + (i % 2);
                des.terrain(selection.fillrect(x, y, x + 6, y + 6), '.');
            }
        } else {
            // nothing
        }
    }

    des.region(selection.area(1, 1, 73, 16), 'lit');

    des.stair('up');
    des.stair('down');

    des.non_diggable();

    for (let i = 1; i <= 15; i++) {
        des.object();
    }

    for (let i = 1; i <= 6; i++) {
        des.trap();
    }

    for (let i = 1; i <= 28; i++) {
        des.monster();
    }
}
